// src/components/TopJobsProjects.js
import React from "react";
import "./TopCandidates.css"; // reuse same styles for consistent UI

const sampleJobs = [
  {
    title: "Frontend Developer",
    domain: "Web Development",
    skills: "React, TailwindCSS, REST APIs",
    budget: "$2,000 - $3,000",
  },
  {
    title: "Data Analyst",
    domain: "Data Science",
    skills: "Python, Pandas, PowerBI",
    budget: "$1,500 - $2,200",
  },
  {
    title: "Mobile App Designer",
    domain: "UI/UX",
    skills: "Figma, Flutter UI",
    budget: "$1,200",
  },
  {
    title: "Machine Learning Engineer",
    domain: "AI & ML",
    skills: "TensorFlow, Scikit-learn",
    budget: "$2,800",
  },
  {
    title: "Full Stack Developer",
    domain: "Software Engineering",
    skills: "Node.js, React, MongoDB",
    budget: "$2,500",
  },
];

function TopJobsProjects() {
  return (
    <div className="top-candidates">
      <h2>Top Jobs & Projects</h2>
      <div className="candidates-list">
        {sampleJobs.map((job, index) => (
          <div className="candidate-card" key={index}>
            <div className="candidate-placeholder">
              {job.title.slice(0, 2).toUpperCase()}
            </div>
            <div className="candidate-info">
              <p className="candidate-name">{job.title}</p>
              <p className="candidate-skills">{job.skills}</p>
            </div>
            <div className="candidate-match">
              <p className="match-percent">{job.domain}</p>
              {/* removed interview-scheduled class usage */}
              <p className="status">{job.budget}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default TopJobsProjects;
